        builder: (context, state) => ChatScreen(cubit: sl<ChatCubit>()),
      ),
      GoRoute(
        path: AppRoutePaths.meusRegistros,
        builder: (context, state) => MeusRegistrosScreen(
          cubit: sl<MeusRegistrosCubit>(),
          searchCubit: sl<EntriesSearchCubit>(),
        ),
        routes: [
          // spec-4-4 (RF07) — `:id` is either a real server id or a
          // still-pending/failed placeholder's synthetic `tempId`
          // (Boundaries: "a valid, un-special-cased navigation target");
          // `EntryDetailCubit` itself decides nothing about which kind it
          // is, it just calls `getById` with it verbatim.
          GoRoute(
            path: ':id',
            builder: (context, state) => EntryDetailScreen(
              cubit: sl<EntryDetailCubit>()..load(state.pathParameters['id']!),
            ),
          ),
        ],
      ),
      GoRoute(
        path: AppRoutePaths.planosDeAcao,
        builder: (context, state) => const ActionPlansPlaceholderScreen(),
      ),
      GoRoute(
        path: AppRoutePaths.configuracoes,
        builder: (context, state) =>
            AccountSettingsScreen(cubit: sl<AccountSettingsCubit>()),
      ),
    ],
  );
}

